INSERT OR REPLACE INTO "OPEX IN" SELECT coalesce(k0."Cost Center", error('cells name a member Cost Center does not have: ' || c."Cost Center")), coalesce(k1."Account", error('cells name a member Account does not have: ' || c."Account")), coalesce(k2."Versions", error('cells name a member Versions does not have: ' || c."Versions")), coalesce(k3."Years", error('cells name a member Years does not have: ' || c."Years")), coalesce(k4."Months", error('cells name a member Months does not have: ' || c."Months")), sum(c.value::DOUBLE)
FROM read_csv('cells/OPEX IN.csv', header = true, all_varchar = true) c LEFT JOIN "dim Cost Center" k0 ON k0.name = c."Cost Center" LEFT JOIN "dim Account" k1 ON k1.name = c."Account" LEFT JOIN "dim Versions" k2 ON k2.name = c."Versions" LEFT JOIN "dim Years" k3 ON k3.name = c."Years" LEFT JOIN "dim Months" k4 ON k4.name = c."Months"
GROUP BY ALL;
